package com.trustvault.controller;
import com.trustvault.model.*; import com.trustvault.repo.*; import com.trustvault.service.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.*; import java.util.*;
@RestController @RequestMapping("/api/users") public class UserController {private final AppUserRepository users;private final AuthorizationService auth;private final PasswordEncoder enc;private final AuditService audit;public UserController(AppUserRepository u,AuthorizationService a,PasswordEncoder e,AuditService x){users=u;auth=a;enc=e;audit=x;}
 @GetMapping public List<Map<String,Object>> list(Authentication a){AppUser me=auth.user(a.getName());if(me.getRole()!=Role.ADMIN&&me.getRole()!=Role.OWNER)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not allowed");return users.findAll().stream().filter(AppUser::isEnabled).map(u->userMap(u)).toList();}
 @PostMapping public Map<String,Object> create(Authentication a,@RequestBody Map<String,String> b){AppUser me=auth.user(a.getName());if(me.getRole()!=Role.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Admin only");String email=b.get("email");if(users.findByEmailIgnoreCase(email).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email exists");Role role=Role.valueOf(b.getOrDefault("role","VIEWER"));AppUser u=users.save(new AppUser(email,enc.encode(b.getOrDefault("password","ChangeMe123!")),b.getOrDefault("fullName",email),role));audit.log(me,AuditAction.USER_CREATED,null,u.getId(),null,"Created "+email);return userMap(u);}
 private Map<String,Object> userMap(AppUser u){ Map<String,Object> m=new LinkedHashMap<>(); m.put("id",u.getId()); m.put("email",u.getEmail()); m.put("fullName",u.getFullName()); m.put("role",u.getRole()); return m; }
 @PatchMapping("/{id}/disable") public void disable(Authentication a,@PathVariable String id){AppUser me=auth.user(a.getName());if(me.getRole()!=Role.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Admin only");AppUser u=auth.user(id);if(u.getId().equals(me.getId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Cannot disable yourself");u.setEnabled(false);users.save(u);audit.log(me,AuditAction.USER_DISABLED,null,id,null,"User disabled; existing JWTs fail on next request");}
}
